9	    * { box-sizing:border-box; }
10	    body { margin:0; background:#f3f5f1; color:var(--ink); font:16px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
11	    main { width:min(920px,calc(100% - 32px)); margin:56px auto; }
12	    header { display:flex; align-items:end; justify-content:space-between; margin-bottom:28px; }
