35	<body>
36	  <main data-harness-ready="true">
37	    <header>
38	      <div><h1>Link Home</h1><p>Your personal collection</p></div>
39	      <div class="count" id="count">0 saved links</div>
40	    </header>
41	    <section class="panel" aria-labelledby="save-heading">
42	      <h2 id="save-heading" style="margin-top:0">Save a link</h2>
43	      <form id="save-form">
44	        <label for="url">Web address</label>
45	        <input id="url" type="url" required placeholder="Paste a web address…" autocomplete="off">
46	        <button id="save" type="submit">Save link</button>
47	      </form>
48	      <div id="message" role="status"></div>
49	    </section>
50	    <section id="empty" class="empty">
51	      <strong>No saved links yet</strong>
52	      Paste your first web address above to begin your collection.
53	    </section>
54	    <article id="card" class="card">
55	      <div class="eyebrow">To read</div>
56	      <h2 id="title"></h2>
57	      <p id="description" class="description"></p>
58	      <div id="source" class="source"></div>
59	    </article>
60	  </main>
61	  <script>
62	    const form = document.querySelector('#save-form');
63	    const input = document.querySelector('#url');
64	    const button = document.querySelector('#save');
65	    const message = document.querySelector('#message');
66	    const presets = {
67	      'developer.mozilla.org': ['JavaScript | MDN', 'JavaScript is a programming language used to make web pages interactive. Explore guides, references, and learning resources.'],
68	      'www.nationalgeographic.com': ['National Geographic', 'Explore stories about science, history, nature, and the world around us.'],
69	      'en.wikipedia.org': ['Wikipedia, the free encyclopedia', 'A free online encyclopedia, created and edited by volunteers around the world.']
70	    };
71	    form.addEventListener('submit', (event) => {
72	      event.preventDefault();
73	      let parsed;
74	      try { parsed = new URL(input.value); } catch { message.textContent = 'Enter a complete web address to save it.'; return; }
75	      button.disabled = true;
76	      message.textContent = 'Getting the page details…';
77	      setTimeout(() => {
78	        const fallbackName = parsed.hostname.replace(/^www\./,'').split('.')[0];
79	        const details = presets[parsed.hostname] || [fallbackName.charAt(0).toUpperCase()+fallbackName.slice(1), `A saved page from ${parsed.hostname}.`];
80	        document.querySelector('#title').textContent = details[0];
81	        document.querySelector('#description').textContent = details[1];
82	        document.querySelector('#source').textContent = parsed.hostname;
83	        document.querySelector('#empty').style.display = 'none';
84	        document.querySelector('#card').classList.add('visible');
85	        document.querySelector('#count').textContent = '1 saved link';
86	        message.textContent = 'Saved with its page details.';
87	        button.disabled = false;
88	      }, 550);
89	    });
90	  </script>
91	</body>
92	</html>
